+function clip(poly: Pt[], p0: Pt, d: Pt): Pt[] | null {
+  const c: Pt = poly.reduce<Pt>((a, p) => [a[0] + p[0] / poly.length, a[1] + p[1] / poly.length], [0, 0]);
