80|            <PictureDraw skin={skin} />
81|          </div>
82|        ) : card.phase === "ready" ? (
83|          <>
84|            {loaded ? null : (
85|              <div className="pane-loading">
86|                <PictureDraw skin={skin} frozen />
87|              </div>
88|            )}
89|            <img
90|              ref={imgRef}
91|              onLoad={markLoaded}
92|              onError={markLoaded}
93|              className={loaded ? `pane-img rv-${skin}` : "pane-img pic-waiting"}
