136|          <button
137|            type="button"
138|            className="pane-x"
139|            onClick={onClear}
140|            aria-label={PICTURE_COPY.remove}
141|            title={PICTURE_COPY.remove}
142|          >
143|            ×
144|          </button>
145|        </div>
146|      ) : null}
