22|      type="button"
23|      ref={popRef}
24|      className="picture-float"
25|      style={{ top: pos.top, left: pos.left }}
26|      onClick={onPick}
27|      aria-label="Picture this"
28|    >
29|      <PictureIcon size={12} />
30|      Picture this
31|    </button>
32|  );
33|}
34|
35|export function InlineFigureView({
36|  figure,
37|  onRemove,
38|  onRetry,
39|  onOpen,
40|  refCb,
41|}: {
42|  figure: InlineFigure;
