50|    figure.phase === "ready" && figure.url ? figure.url : "",
51|  );
52|  if (figure.phase === "loading") {
53|    return (
54|      <figure className="genfig" data-fig={figure.id} ref={refCb as React.Ref<HTMLElement>}>
