64|        <p className="gen-error" role="alert">
65|          {figure.message}{" "}
66|          <button type="button" className="retry-text" onClick={onRetry}>
67|            {PICTURE_COPY.retry}
68|          </button>
69|        </p>
70|      </figure>
71|    );
72|  }
73|  if (!figure.url) return null;
74|  const url = figure.url;
75|  const captioned = `\u201C${truncateCaption(figure.quote)}\u201D`;
76|  return (
77|    <figure className="genfig" data-fig={figure.id} ref={refCb as React.Ref<HTMLElement>}>
78|      <div className="genload">
79|        {loaded ? null : (
80|          <div className="pic-under">
81|            <PictureDraw skin={skin} frozen />
82|          </div>
83|        )}
84|        <img
85|          ref={imgRef}
86|          onLoad={markLoaded}
87|          onError={markLoaded}
88|          className={loaded ? `rv-${skin} gen-ready` : "gen-ready pic-waiting"}
89|          src={url}
90|          alt={captioned}
91|          tabIndex={0}
92|        onClick={(e) => onOpen(url, captioned, e.currentTarget)}
93|        onKeyDown={(e) => {
94|          if (e.key === "Enter") onOpen(url, captioned, e.currentTarget);
95|        }}
96|        />
97|      </div>
